function setAtPath(source, [key, ...rest], value) {
  const copy = Array.isArray(source) ? [...source] : { ...source };
  copy[key] = rest.length ? setAtPath(source?.[key], rest, value) : value;
  return copy;
}
function CatEditor({ row, locale, language, onProfile }) {
  const copy = catEditorText[language] || catEditorText.pl;
  const label = key => catFieldLabels[key]?.[language] || key;
  const profileField = (key, multiline = false) => <Field key={key} multiline={multiline} label={label(key)} value={row.profile[key][locale]} onChange={value => onProfile([key, locale], value)}/>;
  const list = (key, title) => <div><p className="admin-label mb-2">{title}</p><div className="space-y-2">{row.profile[key].map((item, itemIndex) => <Field key={`${key}-${itemIndex}`} multiline label={`${copy.item} ${itemIndex + 1}`} value={item[locale]} onChange={value => onProfile([key, itemIndex, locale], value)}/>)}</div></div>;
  return <details className="group rounded-3xl border border-slate-200 bg-slate-50" open={row.slug === 'mochi'}>
    <summary className="flex cursor-pointer list-none items-center justify-between gap-4 px-5 py-4"><span><strong className="text-xl">{row.name}</strong><span className="ml-3 text-xs font-bold uppercase tracking-wider text-slate-400">/{row.slug}</span></span><span className="rounded-full bg-white px-3 py-1.5 text-xs font-black text-sky-700 shadow-sm group-open:bg-sky-500 group-open:text-white">{copy.profile}</span></summary>
    <div className="border-t border-slate-200 p-4 sm:p-5">
      <div className="mb-3 flex justify-end"><a href={`/koty/${row.slug}`} target="_blank" rel="noreferrer" className="admin-action bg-white"><ExternalLink size={15}/>{copy.open}</a></div>
      <ProfileSection title={copy.main} open><div className="grid gap-3 md:grid-cols-2">{profileField('imageAlt')}{profileField('badge')}{profileField('tagline',true)}{profileField('intro',true)}</div></ProfileSection>
      <ProfileSection title={copy.summary}><div className="grid gap-3 md:grid-cols-2">{profileField('summaryTitle')}{profileField('summary',true)}</div></ProfileSection>
      <ProfileSection title={copy.facts}><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">{['age','birth','joined','origin','healthStatus','healthNote','statusNote'].map(key=>profileField(key))}</div></ProfileSection>
      <ProfileSection title={copy.history}><div className="grid gap-3 md:grid-cols-2">{profileField('historyLabel')}{profileField('historyTitle')}</div><div className="mt-3">{list('story',copy.paragraph)}</div></ProfileSection>
      <ProfileSection title={copy.health}>{profileField('healthIntro',true)}<div className="mt-3">{list('health',copy.item)}</div></ProfileSection>
      <ProfileSection title={copy.character}><div className="grid gap-3 md:grid-cols-2">{profileField('friendshipTitle')}{profileField('friendship',true)}<div className="md:col-span-2">{profileField('signal',true)}</div></div><div className="mt-4 grid gap-3 md:grid-cols-3">{row.profile.traits.map((trait, traitIndex)=><div key={traitIndex} className="rounded-2xl bg-white p-3"><p className="admin-label mb-2">{copy.trait} {traitIndex+1}</p><Field label={copy.value} value={trait.value[locale]} onChange={value=>onProfile(['traits',traitIndex,'value',locale],value)}/><Field label={copy.label} value={trait.label[locale]} onChange={value=>onProfile(['traits',traitIndex,'label',locale],value)}/></div>)}</div></ProfileSection>
      <ProfileSection title={copy.preferences}><div className="grid gap-4 lg:grid-cols-2"><div>{profileField('likesIntro',true)}<div className="mt-3">{list('likes',copy.item)}</div></div><div>{profileField('boundariesIntro',true)}<div className="mt-3">{list('boundaries',copy.item)}</div></div></div></ProfileSection>
      <ProfileSection title={copy.routine}><div className="grid gap-3 md:grid-cols-2">{profileField('routineTitle')}{profileField('routineIntro',true)}</div><div className="mt-4 space-y-3">{row.profile.routine.map((item,itemIndex)=><div key={itemIndex} className="grid gap-2 rounded-2xl bg-white p-3 sm:grid-cols-[160px_1fr]"><Field label={copy.time} value={item.time[locale]} onChange={value=>onProfile(['routine',itemIndex,'time',locale],value)}/><Field multiline label={`${copy.item} ${itemIndex+1}`} value={item.text[locale]} onChange={value=>onProfile(['routine',itemIndex,'text',locale],value)}/></div>)}</div></ProfileSection>
      <ProfileSection title={copy.home}><div className="grid gap-3 md:grid-cols-2">{['placeLabel','placeTitle','placeText','sideTitle','sideText'].map(key=>profileField(key,['placeText','sideText'].includes(key)))}</div></ProfileSection>
      <ProfileSection title={copy.seo}>{profileField('seoDescription',true)}</ProfileSection>
    </div>
  </details>;
}
function ProfileSection({ title, children, open = false }) { return <details open={open} className="mb-3 rounded-2xl border border-slate-200 bg-white last:mb-0"><summary className="cursor-pointer px-4 py-3 text-sm font-black text-slate-700">{title}</summary><div className="border-t border-slate-100 p-4">{children}</div></details>; }

async function prepareImage(file) {
  if (!file?.type?.startsWith('image/')) throw new Error('INVALID_IMAGE');
  const bitmap = await createImageBitmap(file);
  const scale = Math.min(1, 1600 / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.round(bitmap.width * scale)); canvas.height = Math.max(1, Math.round(bitmap.height * scale));
  canvas.getContext('2d').drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  bitmap.close?.();
  const qualitySteps = [.84,.76,.68,.6];
  for (const quality of qualitySteps) {
    const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/webp', quality));
    if (blob && blob.size <= 780000) return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(blob); });
  }
  throw new Error('IMAGE_TOO_LARGE');
}
function ImageUploader({ value, onChange, label, help, uploading }) {
  const [busy,setBusy]=useState(false), [error,setError]=useState('');
  const upload=async event=>{const file=event.target.files?.[0];if(!file)return;setBusy(true);setError('');try{const dataUrl=await prepareImage(file);const body=await api('/api/media',{method:'POST',body:JSON.stringify({dataUrl,name:file.name})});onChange(body.url);}catch{setError('Не удалось загрузить изображение. Выберите другой файл.');}finally{setBusy(false);event.target.value='';}};
  return <div className="mb-3"><div className="mb-3 aspect-[4/3] overflow-hidden rounded-2xl bg-slate-200">{value?<img src={value} alt="" className="h-full w-full object-cover"/>:<span className="grid h-full place-items-center text-slate-400"><ImagePlus size={28}/></span>}</div><label className="admin-action w-fit cursor-pointer bg-white"><ImagePlus size={16}/>{busy?uploading:label}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={upload} className="sr-only"/></label><p className="mt-2 text-xs font-semibold text-slate-500">{error||help}</p></div>;
}
function downloadBookingsCsv(rows) {
  const fields=['id','date','time','guests','name','email','status','eventTitle','notes','adminNote','createdAt'];
  const escape=value=>`"${String(value??'').replace(/"/g,'""')}"`;
  const csv='\ufeff'+[fields.join(';'),...rows.map(row=>fields.map(field=>escape(row[field])).join(';'))].join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
  const link=document.createElement('a');link.href=url;link.download=`niebieski-kot-bookings-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(url);
}
function AvailabilityPanel({ data, change, language, locale, tr, t }) { const statusLabel = language === 'ru' ? 'Статус' : language === 'en' ? 'Status' : 'Status'; const noteLabel = language === 'ru' ? 'Подпись' : language === 'en' ? 'Label' : 'Podpis'; return <Panel icon={Users} title={language === 'ru' ? 'Свободные места' : language === 'en' ? 'Availability' : 'Dostępność'}><SelectField label={statusLabel} value={data.availability.status} onChange={v => change(c => ({ ...c, availability: { ...c.availability, status: v } }))} options={['calm', 'busy', 'almost-full', 'full'].map(v => [v, statusText[v][locale]])}/><Field label={noteLabel} value={data.availability.note[locale]} onChange={v => change(c => ({ ...c, availability: { ...c.availability, note: { ...c.availability.note, [locale]: v } } }))}/><Field label={t.tableLimit} type="number" value={data.bookingSettings.maxTables} onChange={v => change(c => ({ ...c, bookingSettings: { ...c.bookingSettings, maxTables: Number(v) } }))}/><p className="mt-2 text-xs font-semibold text-slate-500">{t.tableLimitHelp}</p></Panel>; }
function CalendarSettingsPanel({ data, change, language }) { const [blockedDate, setBlockedDate] = useState(''); const [specialDate, setSpecialDate] = useState(''); const [specialSlots, setSpecialSlots] = useState('10:00, 12:30'); const copy = language === 'ru' ? { title: 'Расширенный календарь', blocked: 'Заблокированные даты', special: 'Исключение: рабочая дата и слоты', add: 'Добавить', remove: 'Удалить', hint: 'Заблокированные даты недоступны для бронирования. Для исключения укажите дату и часы через запятую.' } : language === 'en' ? { title: 'Advanced calendar', blocked: 'Blocked dates', special: 'Exception: open date and slots', add: 'Add', remove: 'Remove', hint: 'Blocked dates cannot be booked. Add an exception with comma-separated time slots.' } : { title: 'Kalendarz rozszerzony', blocked: 'Zablokowane daty', special: 'Wyjątek: otwarty dzień i godziny', add: 'Dodaj', remove: 'Usuń', hint: 'Zablokowane terminy nie przyjmują rezerwacji. Godziny wyjątku wpisz po przecinku.' }; const addBlocked = () => { if (!blockedDate || data.bookingSettings.blockedDates.includes(blockedDate)) return; change(c => ({ ...c, bookingSettings: { ...c.bookingSettings, blockedDates: [...c.bookingSettings.blockedDates, blockedDate].sort() } })); setBlockedDate(''); }; const addSpecial = () => { const slots = specialSlots.split(',').map(value => value.trim()).filter(value => /^\d{2}:\d{2}$/.test(value)); if (!specialDate || !slots.length) return; change(c => ({ ...c, bookingSettings: { ...c.bookingSettings, specialDates: [...c.bookingSettings.specialDates.filter(row => row.date !== specialDate), { date: specialDate, slots }] } })); setSpecialDate(''); }; return <Panel icon={CalendarDays} title={copy.title} wide><p className="mb-4 text-sm text-slate-500">{copy.hint}</p><div className="grid gap-3 md:grid-cols-[1fr_auto]"><Field label={copy.blocked} type="date" value={blockedDate} onChange={setBlockedDate}/><button type="button" onClick={addBlocked} className="admin-action self-end">{copy.add}</button></div><div className="mt-3 flex flex-wrap gap-2">{data.bookingSettings.blockedDates.map(date => <span key={date} className="inline-flex items-center gap-2 rounded-full bg-rose-50 px-3 py-2 text-sm font-bold text-rose-700">{date}<button type="button" onClick={() => change(c => ({ ...c, bookingSettings: { ...c.bookingSettings, blockedDates: c.bookingSettings.blockedDates.filter(item => item !== date) } }))} aria-label={`${copy.remove} ${date}`}>×</button></span>)}</div><div className="mt-5 grid gap-3 md:grid-cols-[1fr_1.5fr_auto]"><Field label={copy.special} type="date" value={specialDate} onChange={setSpecialDate}/><Field label={language === 'ru' ? 'Слоты' : language === 'en' ? 'Slots' : 'Godziny'} value={specialSlots} onChange={setSpecialSlots}/><button type="button" onClick={addSpecial} className="admin-action self-end">{copy.add}</button></div><div className="mt-3 space-y-2">{data.bookingSettings.specialDates.map(row => <div key={row.date} className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-slate-50 px-4 py-3 text-sm"><span className="font-black">{row.date}</span><span className="font-semibold text-slate-500">{row.slots.join(', ')}</span><button type="button" onClick={() => change(c => ({ ...c, bookingSettings: { ...c.bookingSettings, specialDates: c.bookingSettings.specialDates.filter(item => item.date !== row.date) } }))} className="text-sm font-bold text-rose-600">{copy.remove}</button></div>)}</div></Panel>; }
function AnalyticsPanel({ language, feature, analytics, bookings }) { const title = language === 'ru' ? 'Статистика' : language === 'en' ? 'Statistics' : 'Statystyka'; return <Panel icon={BarChart3} title={title} wide><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><StatCard label={feature.pageviews} value={analytics.summary?.pageviews || 0}/><StatCard label={feature.visits} value={analytics.summary?.visits || 0}/><StatCard label={feature.clicks} value={analytics.summary?.clicks || 0}/><StatCard label={feature.bookingCount} value={bookings.length}/></div><div className="mt-5 grid gap-4 lg:grid-cols-2"><MetricList title={feature.popularPages} values={analytics.pages} empty={feature.noStats}/><MetricList title={feature.popularCats} values={analytics.cats} empty={feature.noStats}/></div></Panel>; }
function StatCard({label,value}) { return <div className="rounded-2xl bg-slate-950 p-5 text-white"><p className="text-xs font-bold uppercase tracking-wider text-slate-400">{label}</p><strong className="mt-2 block text-4xl font-black">{Number(value).toLocaleString()}</strong></div>; }
function MetricList({title,values={},empty}) { const rows=Object.entries(values).sort((a,b)=>b[1]-a[1]).slice(0,8); return <div className="rounded-2xl bg-slate-50 p-5"><h3 className="mb-4 font-black">{title}</h3>{rows.length?<div className="space-y-2">{rows.map(([name,count])=><div key={name} className="flex items-center justify-between gap-4 rounded-xl bg-white px-4 py-3 text-sm"><span className="truncate font-semibold">{name}</span><strong>{count}</strong></div>)}</div>:<p className="text-sm text-slate-500">{empty}</p>}</div>; }

function Login({ t, tr, configured, username, setUsername, password, setPassword, show, setShow, busy, message, onSubmit }) { const usernameLabel = t.login === 'Вход в админ-панель' ? 'Пользователь / e-mail' : t.login === 'Admin sign in' ? 'Username / e-mail' : 'Użytkownik / e-mail'; return <Splash><div className="w-full max-w-md rounded-[2rem] border border-slate-200 bg-white p-7 shadow-xl sm:p-9"><Brand/><p className="mt-8 text-sm font-extrabold uppercase tracking-[.18em] text-sky-600">{tr('Panel administracyjny')}</p><h1 className="mt-2 text-3xl font-black">{t.login}</h1>{!configured && <Notice kind="warning">{t.notReady}</Notice>}{message && <Notice kind="error">{message.text}</Notice>}<form onSubmit={onSubmit} className="mt-6"><label className="admin-label">{usernameLabel}<input autoFocus autoComplete="username" value={username} onChange={e => setUsername(e.target.value)} className="admin-input mt-1.5"/></label><label className="admin-label mt-4">{t.password}<span className="relative mt-2 block"><input autoComplete="current-password" type={show ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)} className="admin-input pr-12"/><button type="button" onClick={() => setShow(!show)} aria-label={t.showPassword} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-slate-500">{show ? <EyeOff size={18}/> : <Eye size={18}/>}</button></span></label><button disabled={busy || !password || !username.trim()} className="mt-5 flex w-full items-center justify-center gap-2 rounded-full bg-slate-950 px-5 py-3 font-extrabold text-white disabled:opacity-40">{busy && <Loader2 className="animate-spin" size={17}/>} {t.enter}</button></form><Link to="/" className="mt-5 block text-center text-sm font-bold text-sky-600">← {tr('Открыть сайт')}</Link></div></Splash>; }
function Splash({ children }) { return <div className="grid min-h-screen place-items-center bg-[#f7f8f4] p-5">{children}</div>; }
function Brand() { return <Link to="/" className="flex items-center gap-2.5"><span className="grid h-10 w-10 place-items-center rounded-full bg-sky-500 text-white"><Cat size={20}/></span><span className="text-lg font-extrabold">Niebieski Kot<span className="text-sky-500">.</span></span></Link>; }
function Panel({ icon: Icon, title, children, wide = false, hidden = false }) { if(hidden)return null; return <section className={`rounded-[2rem] border border-slate-200 bg-white p-5 shadow-sm sm:p-7 ${wide ? 'lg:col-span-2' : ''}`}><h2 className="mb-5 flex items-center gap-3 text-xl font-black"><span className="grid h-10 w-10 place-items-center rounded-xl bg-sky-100 text-sky-600"><Icon size={19}/></span>{title}</h2>{children}</section>; }
function Rows({ children }) { return <div className="space-y-3">{children}</div>; }
function Row({ children }) { return <div className="grid items-end gap-2 sm:grid-cols-[1fr_1fr_auto]">{children}</div>; }
function Card({ children }) { return <div className="rounded-2xl bg-slate-50 p-4">{children}</div>; }
function Field({ label, value, onChange = () => {}, type = 'text', multiline = false, readOnly = false }) { const Tag = multiline ? 'textarea' : 'input'; return <label className="admin-label">{label}<Tag type={type} min={type === 'number' ? '0' : undefined} maxLength={multiline ? 2000 : 500} value={value} readOnly={readOnly} onChange={e => onChange(e.target.value)} className={`admin-input mt-1.5 min-h-11 ${multiline ? 'resize-y' : ''} ${readOnly ? 'bg-slate-100 text-slate-500' : ''}`}/></label>; }
function SelectField({ label, value, onChange, options }) { return <label className="admin-label mb-2">{label}<select value={value} onChange={e => onChange(e.target.value)} className="admin-input mt-1.5">{options.map(([key, text]) => <option key={key} value={key}>{text}</option>)}</select></label>; }
function Toggle({ label, checked, onChange }) { return <label className="flex cursor-pointer items-center gap-2 text-xs font-bold text-slate-600"><input type="checkbox" checked={checked} onChange={e => onChange(e.target.checked)} className="h-4 w-4 accent-sky-500"/>{label}</label>; }
function Remove({ onClick, label }) { return <button type="button" aria-label={label} onClick={onClick} className="grid h-10 w-10 place-items-center rounded-xl border border-slate-200 text-slate-400 hover:border-rose-300 hover:text-rose-500"><X size={16}/></button>; }
function Add({ onClick, children }) { return <button type="button" onClick={onClick} className="mt-4 rounded-full border border-dashed border-sky-300 px-4 py-2 text-sm font-bold text-sky-700 hover:bg-sky-50">+ {children}</button>; }
function Notice({ kind, children }) { const style = kind === 'success' ? 'border-emerald-200 bg-emerald-50 text-emerald-800' : kind === 'warning' ? 'border-amber-200 bg-amber-50 text-amber-900' : 'border-rose-200 bg-rose-50 text-rose-800'; return <p role={kind === 'error' ? 'alert' : 'status'} className={`my-4 flex items-start gap-2 rounded-2xl border p-4 text-sm font-semibold ${style}`}>{kind === 'success' && <Check size={17}/>} {children}</p>; }
